.mouse {
    position: absolute;
    left: 0;
    right: 0;
    margin: auto;
    bottom: -20px;
    width: 24px;
    height: 42px;
    border-radius: 30px;
    opacity: 1;
    z-index: 999;
    overflow: hidden;
}

    .mouse:after {
        display: block;
        content: "";
        position: absolute;
        left: 12px;
        top: 10px;
        width: 4px;
        height: 4px;
        margin-left: -3px;
        border-radius: 2px;
        animation: mouse-wheel 2.5s cubic-bezier(0.77, 0, 0.175, 1) infinite;
    }

@keyframes mouse-wheel {
    0% {
        transform: translateY(0);
        opacity: 0;
    }

    10% {
        transform: translateY(0);
        opacity: 1;
    }

    30% {
        transform: translateY(0);
        height: 4px;
    }

    50% {
        transform: translateY(0);
        height: 20px;
    }

    70% {
        transform: translateY(15px);
        height: 4px;
        opacity: 1;
    }

    90% {
        opacity: 0;
    }

    100% {
        transform: translateY(15px);
        opacity: 0;
    }
}


